/>

// Drive it from outside with status (pending, approved, denied). Pass onDecision to hear the answer.
// Y, A and N answer while the card has focus, so they never fire on a page the person is only reading.
// Pass autoFocus to focus the card once it is in view, so a gate that appears mid-task is answerable at once.
// The countdown only runs while the card is in view, so an unseen request never denies itself.

import { AgentDiffReview } from "@/components/design-for-ai/agent-diff-review";

<AgentDiffReview
  agent="Atlas"
  title="Round money once, in each currency's own minor unit"
  changes={proposal.files} // [{ path, language?, hunks: [{ id, oldStart, newStart, scope, note?, lines: [{ kind, text }] }] }]
  view="unified"
  onDecisionsChange={(d) => saveDraft(d)}
  onApply={(ids) => agent.applyHunks(ids)} // return a promise for the applying state; reject it to stay in review
/>

// Hunk ids must be unique across the change set: decisions are keyed by them.
// Keyboard: with a hunk focused, A accepts, R rejects or reopens, J and K move between hunks.
// Split view needs about 900px of width; narrower, the same diff reads as unified.
// No virtualisation: keep a review to a few hundred lines, or page it by file.

import { AgentPlan } from "@/components/design-for-ai/agent-plan-steps";

const [state, setState] = useState<"draft" | "running" | "paused" | "complete" | "failed">("draft");

<AgentPlan
  title="Backfill the ledger from billing events"
  steps={planFromAgent}
  state={state}
  onStateChange={setState}
  onApprove={(steps) => api.runs.start(runId, steps)}
/>

// steps: { id, title, duration?, substeps?, outcome?: "done" | "skipped" | "failed", reason? }
// Drive the run from your own backend by setting `state` as each step lands, or let the component tick.

import { AgentRunTrace } from "@/components/design-for-ai/agent-run-trace";
import type { TraceSpan } from "@/components/design-for-ai/agent-run-trace";

// Flat spans from your tracer: parentId links the tree, start and duration are in ms.
const spans: TraceSpan[] = run.spans.map((s) => ({
  id: s.spanId,
  parentId: s.parentSpanId ?? null,
  name: s.name,
  kind: s.attributes["gen_ai.operation"] ? "llm" : s.kind === "tool" ? "tool" : "step",
  start: s.startMs,
  duration: s.endMs - s.startMs,
  model: s.attributes["gen_ai.request.model"],
  tokensIn: s.attributes["gen_ai.usage.input_tokens"],
  tokensOut: s.attributes["gen_ai.usage.output_tokens"],
  cost: s.costUsd,
  input: s.input,
  output: s.output,
}));

<AgentRunTrace
  trace={spans}
  runName="support-triage"
  runLabel="Ticket #4471"
  runId={run.id}
  onSelectSpan={(span) => setInspected(span?.id)}
/>

// Tooltips and the details pane are positioned inside the component, so it needs no portal.

import { AgentsBudgetGuard } from "@/components/design-for-ai/agents-budget-guard";

<AgentsBudgetGuard
  agent="Atlas"
  run="Q3 churn analysis"
  step={14}
  action={{ title: "Summarise 412 support tickets", tool: "tickets.summarise", detail: "Halcyon Pro · 1.18M tokens in" }}
  budgets={[
    { id: "spend", label: "Spend", kind: "money", used: 21.3, next: 6.2, cap: 25 },
    { id: "tokens", label: "Tokens", kind: "tokens", used: 3_420_000, next: 1_276_000, cap: 5_000_000 },
  ]}
  history={spendPerStep}
  onDecision={async (d) => {
    if (d.verdict === "raise") await runs.setCap(runId, d.cap);
    if (d.verdict === "stop") await runs.stop(runId);
    else await runs.resume(runId);
  }}
/>

// Return a promise from onDecision to hold the button busy; reject it to keep the card open with an error.
// Y, R and S answer while the card has focus. Pass status to drive it from outside.

import { AgentsDependencyBoard } from "@/components/design-for-ai/agents-dependency-board";
import type { PlanTask } from "@/components/design-for-ai/agents-dependency-board";

const tasks: PlanTask[] = plan.steps.map((s) => ({
  id: s.id,
  title: s.title,
  agent: s.assignee,
  estimate: s.estimateMinutes,
  status: s.state, // "done" | "running" | "queued" | "failed"
  progress: s.progress, // 0–1 while running
  dependsOn: s.needs,
  note: s.lastError ?? s.summary,
}));

<AgentsDependencyBoard
  title={plan.title}
  planId={plan.id}
  tasks={tasks}
  onAction={async (task, action) => {
    // Reject to show the error under the button; resolve once the runner has accepted it.
    await runner[action](task.id);
  }}
/>

import { AgentsRunReplay } from "@/components/design-for-ai/agents-run-replay";
import type { ReplayEvent } from "@/components/design-for-ai/agents-run-replay";

// One event per prompt, thinking span, tool call and reply. Times are ms from the start of the run.
const events: ReplayEvent[] = run.steps.map((s) => ({
  id: s.id,
  at: s.startedAt - run.startedAt,
  duration: s.endedAt - s.startedAt,
  kind: s.type, // "prompt" | "thinking" | "tool" | "reply"
  title: s.type === "tool" ? s.toolName : s.author,
  args: s.toolArgs,
  body: s.output ?? s.text,
  status: s.error ? "error" : "ok",
  tokens: s.usage?.totalTokens,
  cost: s.costUsd,
  files: s.filesChanged, // [{ path, added, removed }]
  tests: s.testSummary, // { passed, failed }
}));

<AgentsRunReplay
  run={{ id: run.id, title: run.title, agent: "Atlas", requester: run.user.name, repo: run.repo, outcome: "completed" }}
  events={events}
  onEventChange={(event) => setInspected(event?.id)}
/>

