// Your search drives it: pass sources as they arrive, then the answer as it streams.
export default function AnswerPage({ run, ask }) {
  return (
    <SearchAnswer
      query={run.query}
      status={run.status} // "searching" | "answering" | "done"
      sources={run.sources} // [{ id, title, domain, snippet, date?, href? }], in ranked order
      answer={run.text} // paragraphs split by a blank line; [n] cites the nth source
      followUps={run.related} // slide in once done; a click puts one in the query box
      elapsedMs={run.ms}
      maxSources={6}
      density="reading" // or "compact" for a side panel
      onAsk={(q) => ask(q)}
    />
  );
}

