  capture={{ id: log.requestId, capturedAt: "14:02:11", source: "production · checkout-api", request, response }}
  onReplay={async (req, signal) => {
    const started = performance.now();
    const res = await fetch(req.url, {
      method: req.method,
      headers: req.headers.filter((h) => h.enabled !== false).map((h) => [h.name, h.value]),
      body: req.method === "GET" ? undefined : req.body,
      signal,
    });
    return {
      status: res.status,
      statusText: res.statusText,
      headers: [...res.headers],
      body: await res.text(),
      durationMs: Math.round(performance.now() - started),
    };
  }}
/>

